events.hero=events.neutral;
const state={preset:"neutral",year:2026,month:7,selectedDay:22,character:"arlecchino",mode:"birthday",view:"month",filter:"all"};
const months=["1月","2月","3月","4月","5月","6月","7月","8月","9月","10月","11月","12月"];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const tokenMap={baseStart:"--base-start",baseMid:"--base-mid",baseEnd:"--base-end",haloPrimary:"--halo-primary",haloSecondary:"--halo-secondary",stageDeep:"--stage-deep",stageBorder:"--stage-border",surface:"--surface",surfaceBorder:"--surface-border",accent:"--accent",eventBirthday:"--event-birthday",eventRelease:"--event-release",contextStrength:"--context-strength",heroStrength:"--hero-strength"};
function applyTokens(name){Object.entries(tokenMap).forEach(([key,css])=>document.documentElement.style.setProperty(css,profiles[name][key]));}
function currentEvents(){return (events[state.preset]||[]).filter(event=>{if(event.type!==state.mode)return false;if(state.filter==="all")return true;return event.people.some(id=>state.filter==="genshin"?characters[id]?.game==="原神":characters[id]?.game==="星穹铁道");});}
function setImage(element,fallback,character){element.src=character.image;element.alt=`${character.name}角色立绘`;element.hidden=false;fallback.hidden=true;element.onerror=()=>{element.hidden=true;fallback.hidden=false;$("#fallbackLetter").textContent=character.name.slice(0,1);};}
function setCharacter(id){const character=characters[id]||characters.arlecchino;state.character=character.id;const preset=presets[state.preset];setImage($("#stageImage"),$("#fallback"),character);$("#stageImage").style.objectPosition=preset.position;$("#stageName").textContent=character.name;$("#stageEnglish").textContent=character.en;$("#stageAffiliation").textContent=character.affiliation;$("#stageDate").textContent=`${character.date} · ${preset.signal}`;updateHero(character);}
function updateHero(character=characters[state.character]){$("#heroImage").src=character.image;$("#heroImage").alt=`${character.name}全屏角色立绘`;$("#heroName").textContent=character.name;$("#heroEnglish").textContent=character.en;$("#heroDate").textContent=character.iso;$("#heroAffiliation").textContent=`${character.game} · ${character.affiliation}`;$("#heroKicker").textContent=state.mode==="birthday"?"生日记忆":"实装纪念";$("#heroProfile").textContent=`${presets[state.preset].profile.toUpperCase()} / CHARACTER ACCENT`;}
function makeAvatar(id,type){const character=characters[id],button=document.createElement("button");button.type="button";button.className="avatar";button.style.setProperty("--event-color",type==="birthday"?"var(--event-birthday)":"var(--event-release)");button.title=character.name;button.setAttribute("aria-label",`选择${character.name}`);button.innerHTML=`<img src="${character.image}" alt="" />`;button.addEventListener("click",event=>{event.stopPropagation();setCharacter(id);selectDay(Number(button.closest(".day").dataset.day),id,type);});return button;}
function renderCalendar(){const grid=$("#calendarGrid");grid.querySelectorAll(".day").forEach(cell=>cell.remove());const first=new Date(state.year,state.month,1),offset=(first.getDay()+6)%7,start=new Date(state.year,state.month,1-offset),byDay=new Map(currentEvents().map(event=>[event.day,event]));for(let index=0;index<42;index++){const date=new Date(start);date.setDate(start.getDate()+index);const inMonth=date.getMonth()===state.month,day=date.getDate(),event=inMonth?byDay.get(day):null,cell=document.createElement("div");cell.className="day";cell.dataset.day=day;cell.tabIndex=0;cell.setAttribute("role","button");cell.setAttribute("aria-label",`${date.getFullYear()}年${date.getMonth()+1}月${day}日`);if(!inMonth)cell.classList.add("outside");if(inMonth&&day===state.selectedDay)cell.classList.add("selected");if(date.getFullYear()===2026&&date.getMonth()===7&&day===24){cell.classList.add("today");cell.innerHTML='<span class="today-label">今天</span>';}
const number=document.createElement("span");number.className="num";number.textContent=day;cell.append(number);if(event){cell.style.setProperty("--event-color",event.type==="birthday"?"var(--event-birthday)":"var(--event-release)");const pin=document.createElement("i");pin.className="pin";cell.append(pin);if(event.people.length){const group=document.createElement("div");group.className="avatars"+(event.people.length===1?" single":"")+(event.people.length>=4?" dense":"");event.people.slice(0,3).forEach(id=>group.append(makeAvatar(id,event.type)));if(event.people.length>3){const more=document.createElement("span");more.className="more";more.textContent=`+${event.people.length-3}`;group.append(more);}cell.append(group);}}cell.addEventListener("click",()=>selectDay(day,event?.people[0],event?.type));cell.addEventListener("keydown",keyboard=>{if(keyboard.key==="Enter"||keyboard.key===" "){keyboard.preventDefault();selectDay(day,event?.people[0],event?.type);}});grid.append(cell);}$("#calendarTitle").textContent=`${state.year}年 ${months[state.month]}`;$("#monthCount").textContent=`${state.year}年${state.month+1}月 · ${currentEvents().length} 条事件`;updateSelected();}
function selectDay(day,id,type){state.selectedDay=day;if(id)setCharacter(id);updateSelected(type);renderCalendar();}
function updateSelected(type){const event=currentEvents().find(item=>item.day===state.selectedDay),resolved=type||event?.type||state.mode,character=characters[event?.people[0]||state.character];$("#selectedDay").textContent=state.selectedDay;$("#selectedMonth").textContent=months[state.month];$("#selectedType").textContent=resolved==="birthday"?"生日":"实装";$("#selectedName").textContent=event?character.name:"当天无角色纪念";$("#selectedNote").textContent=event?character.affiliation:"选择有标记的日期查看角色";}
function updateControls(){$$("[data-mode]").forEach(button=>button.classList.toggle("active",button.dataset.mode===state.mode));$$("[data-view]").forEach(button=>button.classList.toggle("active",button.dataset.view===state.view));$$("[data-filter]").forEach(button=>button.classList.toggle("active",button.dataset.filter===state.filter));document.body.dataset.view=state.view;}
function applyPreset(name,updateUrl=true){const preset=presets[name]||presets.neutral;state.preset=presets[name]?name:"neutral";state.year=preset.year;state.month=preset.month;state.character=preset.character;state.selectedDay=preset.selectedDay ?? Number(characters[preset.character].date.slice(3,5));state.filter=name==="sumeru"?"genshin":name==="hsr"?"hsr":"all";state.mode=name==="hsr"?"release":"birthday";applyTokens(preset.profile);$("#calendarEyebrow").textContent=preset.eyebrow;$("#contextSummary").textContent=preset.context;$("#stageKicker").textContent=preset.kicker;$("#stageContext").textContent=preset.stageContext;$("#stageSignal").textContent=preset.signal;setCharacter(preset.character);updateControls();renderCalendar();$$('[data-state]').forEach(button=>button.classList.toggle("active",button.dataset.state===state.preset));if(updateUrl){const url=new URL(location.href);url.searchParams.set("state",state.preset);history.replaceState({},"",url);}if(preset.openHero)setTimeout(openHero,80);}
function openHero(){updateHero();if(!$("#heroDialog").open)$("#heroDialog").showModal();}function closeHero(){if($("#heroDialog").open)$("#heroDialog").close();}
function toast(message){const node=$("#toast");node.textContent=message;node.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove("show"),1700);}
function renderSearch(query=""){const value=query.trim().toLowerCase(),box=$("#searchResults");box.replaceChildren();Object.values(characters).filter(c=>!value||c.name.includes(value)||c.en.toLowerCase().includes(value)||c.game.includes(value)).forEach(character=>{const button=document.createElement("button");button.type="button";button.className="result";button.innerHTML=`<img src="${character.image}" alt=""/><div><strong>${character.name}</strong><small>${character.en} · ${character.affiliation}</small></div><span>${character.game}</span>`;button.addEventListener("click",()=>{setCharacter(character.id);$("#searchDialog").close();});box.append(button);});}
$$('[data-state]').forEach(button=>button.addEventListener("click",()=>applyPreset(button.dataset.state)));$("#prevMonth").addEventListener("click",()=>{state.month--;if(state.month<0){state.month=11;state.year--;}renderCalendar();});$("#nextMonth").addEventListener("click",()=>{state.month++;if(state.month>11){state.month=0;state.year++;}renderCalendar();});$("#today").addEventListener("click",()=>{state.year=2026;state.month=7;state.selectedDay=24;renderCalendar();toast("已回到 2026年8月24日");});$$('[data-mode]').forEach(button=>button.addEventListener("click",()=>{state.mode=button.dataset.mode;updateControls();renderCalendar();updateHero();}));$$('[data-view]').forEach(button=>button.addEventListener("click",()=>{state.view=button.dataset.view;updateControls();}));$$('[data-filter]').forEach(button=>button.addEventListener("click",()=>{state.filter=button.dataset.filter;$("#contextSummary").textContent=state.filter==="all"?presets[state.preset].context:state.filter==="genshin"?"原神":"星穹铁道";updateControls();renderCalendar();}));$("#clearState").addEventListener("click",()=>{applyPreset("neutral");toast("已清除筛选并回到中性主题");});$("#heroOpen").addEventListener("click",openHero);$("#selectedOpen").addEventListener("click",openHero);$("#heroClose").addEventListener("click",closeHero);$("#heroReturn").addEventListener("click",closeHero);$("#searchOpen").addEventListener("click",()=>{renderSearch();$("#searchDialog").showModal();setTimeout(()=>$("#searchInput").focus(),40);});$("#searchInput").addEventListener("input",event=>renderSearch(event.currentTarget.value));$("#searchDialog").addEventListener("click",event=>{if(event.target===$("#searchDialog"))$("#searchDialog").close();});
applyPreset(new URLSearchParams(location.search).get("state")||"neutral",false);




